import { loader } from "fumadocs-core/source";
// `.source/server.ts` is generated by `fumadocs-mdx`; the include in
// tsconfig (".source/**/*.ts") + the pre-build step in package.json
// ensure this resolves at type-check + build time. Relative (not `@/`) so the
// path survives shadcn's monorepo import rewriting when scaffolded into apps/docs.
import { docs } from "../.source/server";
import { ProjectAboutMarkdown } from "../components/docs/project-about-markdown";
import { ProjectDocumentMarkdown } from "../components/docs/project-document";
import { relatedPageMarkdownComponents } from "../components/docs/related-pages";
import { specimenMarkdownComponents } from "../components/docs/specimen-markdown";
import { TokenConfigurationMarkdown } from "../components/docs/token-configuration";
import { TokenReferenceMarkdown } from "../components/docs/token-reference";

/**
 * Fumadocs source loader. Exposes a page tree + helpers for resolving
 * docs by slug, used by `app/docs/layout.tsx` and the catch-all route.
 */
export const source = loader({
  baseUrl: "/docs",
  source: docs.toFumadocsSource(),
});

/** Resolve a related page against the documentation actually installed in this project. */
export function resolveRelatedPage(href: string): string | undefined {
  if (href === "/docs") return source.getPage([])?.url;
  if (!href.startsWith("/docs/")) return undefined;
  return source.getPage(href.slice("/docs/".length).split("/"))?.url;
}

/** Project-specific Markdown forms for the documentation templates. */
export function markdownComponentsForPage() {
  return {
    ...relatedPageMarkdownComponents(resolveRelatedPage),
    ...specimenMarkdownComponents,
    TokenConfiguration: TokenConfigurationMarkdown,
    TokenReference: TokenReferenceMarkdown,
    ProjectAbout: ProjectAboutMarkdown,
    ProjectDocument: ProjectDocumentMarkdown,
  };
}
